from pathlib import Path
p=Path('/private/tmp/openui-selectors-w2-evidence');s=(p/'run-overrides.mjs').read_text();s=s[:s.index('try{browser=await')]
s+=r'''
const failures=JSON.parse(await fs.readFile(root+'/small-results.json','utf8')).checks.filter(x=>!x.pass),out=[];
try{browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});for(const row of failures){const family=row.name.split('/')[0],d=row.detail,pair={};let index;
for(const arm of ['candidate','baseline']){const p=await browser.newPage({viewport:{width:1280,height:900}});await p.goto(origin+'/'+arm+'-small-'+family+'/index.html');await p.waitForFunction(()=>window.ready&&!!document.querySelector('[data-family]'));await p.waitForTimeout(650);await settle(p);if(arm==='candidate')index=await p.locator('[data-family]').evaluate((e,hook)=>[e,...e.querySelectorAll('*')].findIndex(e=>e.classList.contains(hook)),d.hook);
pair[arm]=await p.locator('[data-family]').evaluate(async(root,{index,d,arm})=>{const e=[root,...root.querySelectorAll('*')][index];if(!e)throw Error('missing counterpart');const rules=[];function walk(rs){for(const r of rs){if(r.selectorText&&r.style&&e.matches(r.selectorText)&&(r.style.getPropertyValue(d.property)||['min-width','max-width','flex-shrink'].some(k=>r.style.getPropertyValue(k))))rules.push({selector:r.selectorText,declarations:r.style.cssText});if(r.cssRules)walk(r.cssRules)}}for(const s of document.styleSheets)try{walk(s.cssRules)}catch{}const prop=d.property,before=getComputedStyle(e).getPropertyValue(prop),selector='.'+(arm==='candidate'?d.hook:[...e.classList].find(c=>/^go\d+$/.test(c))),style=document.createElement('style');style.textContent=selector+'{'+prop+':'+d.wanted+'}';document.head.append(style);getComputedStyle(e).display;await new Promise(r=>requestAnimationFrame(r));await Promise.all(e.getAnimations().filter(a=>a.constructor.name==='CSSTransition').map(a=>a.finished.catch(()=>{})));const originalActual=getComputedStyle(e).getPropertyValue(prop),parentDisplay=getComputedStyle(e.parentElement).display;style.remove();let correctedSelector=selector,correctedValue=d.wanted;
if(prop==='display')correctedValue='grid';else if(d.hook==='openui-image-text-image')correctedValue='137px';else if(d.hook==='openui-steps-root')correctedValue='317px';else if(d.hook==='openui-mark-down-renderer-markdown-root')correctedSelector='.openui-inline-markdown-renderer '+selector;else if(d.hook==='openui-carousel-item-styled')correctedSelector='.openui-sources-container '+selector;else if(d.hook==='openui-tabs-list-styled')correctedSelector='.openui-tabs-container '+selector;
style.textContent=correctedSelector+'{'+prop+':'+correctedValue+'}';document.head.append(style);getComputedStyle(e).display;await new Promise(r=>requestAnimationFrame(r));await Promise.all(e.getAnimations().filter(a=>a.constructor.name==='CSSTransition').map(a=>a.finished.catch(()=>{})));const correctedActual=getComputedStyle(e).getPropertyValue(prop);style.remove();return{index,tag:e.tagName,classes:[...e.classList],property:prop,before,originalSelector:selector,originalWanted:d.wanted,originalActual,parentDisplay,computedMinWidth:getComputedStyle(e).minWidth,computedMaxWidth:getComputedStyle(e).maxWidth,competingRules:rules,correction:{selector:correctedSelector,wanted:correctedValue,actual:correctedActual,pass:correctedActual===correctedValue}};},{index,d,arm});await p.close();}
out.push({original:row,family,pair});await fs.writeFile(root+'/override-dispositions-progress.json',JSON.stringify(out));}await fs.writeFile(root+'/override-dispositions.json',JSON.stringify({browser:browser.version(),records:out},null,2));console.log(JSON.stringify({records:out.length,correctionFailures:out.flatMap(x=>Object.entries(x.pair).filter(([a,d])=>!d.correction.pass).map(([a,d])=>({name:x.original.name,arm:a,correction:d.correction})))}));}finally{if(browser)await browser.close();await new Promise(r=>server.close(r));await fs.writeFile(root+'/dispositions-session-closed.json',JSON.stringify({time:new Date().toISOString(),browserClosed:true,serverClosed:true}));}
'''
(p/'run-dispositions.mjs').write_text(s)
